const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Mekele, Ethiopia
  const mekele = ee.Geometry.Point([39.4753, 13.4967]).buffer(15000); // 15km radius

  // 2. Function to mask clouds for Landsat
  function maskL5(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  function maskL89(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  // 3. Get 1984 data (Landsat 5)
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(mekele)
    .filterDate('1984-01-01', '1984-12-31')
    .map(maskL5);

  const size1984 = await col1984.size().getInfo();
  console.log(`1984 Images: ${size1984}`);

  if (size1984 === 0) {
    console.log('No Landsat 5 data for 1984, trying extended period');
    col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(mekele)
      .filterDate('1984-01-01', '1985-12-31')
      .map(maskL5);
    const size1984_ext = await col1984.size().getInfo();
    if (size1984_ext === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Get 2024-2025 data (Landsat 9, fallback to Landsat 8)
  let col2025 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(mekele)
    .filterDate('2024-01-01', '2025-12-31')
    .map(maskL89);

  const size2025 = await col2025.size().getInfo();
  console.log(`2024-2025 Landsat 9 Images: ${size2025}`);

  if (size2025 === 0) {
    console.log('No Landsat 9 data, trying Landsat 8');
    col2025 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(mekele)
      .filterDate('2023-01-01', '2025-12-31')
      .map(maskL89);
    const size2025_l8 = await col2025.size().getInfo();
    if (size2025_l8 === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 5. Create composite images and calculate NDBI
  const img1984 = col1984.median();
  const img2025 = col2025.median();

  // Calculate NDBI for Landsat 5 (SWIR1=B5, NIR=B4)
  const ndbi1984 = img1984.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');

  // Calculate NDBI for Landsat 8/9 (SWIR1=B6, NIR=B5)
  const ndbi2025 = img2025.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI');

  // 6. Threshold for urban (NDBI > 0.1 indicates built-up area)
  const urban1984 = ndbi1984.gt(0.1);
  const urban2025 = ndbi2025.gt(0.1);

  // 7. Calculate urban area in square meters
  const pixelArea = ee.Image.pixelArea();

  const stats1984 = await urban1984.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: mekele,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count1984 = await urban1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mekele,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2025 = await urban2025.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: mekele,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count2025 = await urban2025.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mekele,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const area1984 = stats1984.NDBI;
  const area2025 = stats2025.NDBI;
  const pixels1984 = count1984.NDBI;
  const pixels2025 = count2025.NDBI;

  console.log(`1984 Valid Pixels: ${pixels1984}`);
  console.log(`2025 Valid Pixels: ${pixels2025}`);

  if (pixels1984 === 0 || pixels2025 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (area1984 === null || area2025 === null || isNaN(area1984) || isNaN(area2025)) {
    console.log('<answer>C3</answer>');
    return;
  }

  const area1984_km2 = area1984 / 1e6;
  const area2025_km2 = area2025 / 1e6;

  console.log(`1984 Urban Area: ${area1984_km2.toFixed(2)} km²`);
  console.log(`2025 Urban Area: ${area2025_km2.toFixed(2)} km²`);
  console.log(`Increase: ${(area2025_km2 - area1984_km2).toFixed(2)} km²`);

  if (area2025_km2 > area1984_km2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
